const uor01Text = $('Extract UOR-01 Text').first().json.data || '';
const uor06Text = $('Extract UOR-06 Text').first().json.data || '';

function parseLines(text) {
  const out = [];
  let failures = 0;
  text.split('\n').filter((l) => l.trim().length > 0).forEach((line) => {
    try { out.push(JSON.parse(line)); } catch (e) { failures++; }
  });
  return { records: out, failures };
}

const uor01 = parseLines(uor01Text);
const uor06 = parseLines(uor06Text);

const contentTagMembers = new Set();
uor06.records.forEach((row) => {
  if (row.tag === 'content_creation_automation' || row.tag === 'social_media_management') {
    (row.member_opportunity_ids || []).forEach((id) => contentTagMembers.add(id));
  }
});

function keywordRegex(term, exact) {
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return exact ? new RegExp(`\\b${escaped}\\b`, 'i') : new RegExp(`\\b${escaped}\\w*`, 'i');
}

const PLATFORMS = [['youtube',false],['tiktok',false],['instagram',false],['twitch',false],['podcast',false],['newsletter',false],['substack',false],['blog',false],['twitter',false]];
const FORMATS = [['short-form video',true],['shorts',false],['reel',false],['long-form video',true],['livestream',true],['live stream',true],['written content',true],['audio',false]];

// --- FIX 1: attention_potential formula, replacing the hardcoded
// 'NOT_DETERMINED' literal. See UOR-07-Build-Log.md for full rationale.
const ATTENTION_POTENTIAL_FORMULA_VERSION = 'uor07-attention-v1-2026-09-08';

const VIEW_COUNT_THRESHOLDS = [
  { min: 100000, score: 10 },
  { min: 10000, score: 7 },
  { min: 1000, score: 4 },
  { min: 100, score: 2 },
  { min: 0, score: 0 },
];
const COMMENT_COUNT_THRESHOLDS = [
  { min: 500, score: 10 },
  { min: 100, score: 7 },
  { min: 20, score: 4 },
  { min: 1, score: 2 },
  { min: 0, score: 0 },
];
const LIKE_COUNT_THRESHOLDS = [
  { min: 5000, score: 10 },
  { min: 500, score: 7 },
  { min: 50, score: 4 },
  { min: 1, score: 2 },
];
const WEIGHT_VIEW = 0.5;
const WEIGHT_COMMENT = 0.3;
const WEIGHT_LIKE = 0.2;
const ATTENTION_STATUS_THRESHOLDS = [
  { min: 70, status: 'HIGH_ATTENTION' },
  { min: 40, status: 'MODERATE_ATTENTION' },
  { min: 10, status: 'LOW_ATTENTION' },
  { min: 0, status: 'MINIMAL_ATTENTION' },
];

function bucketScore(value, thresholds) {
  for (const t of thresholds) if (value >= t.min) return t.score;
  return 0;
}

function computeAttentionPotential(fullRecord) {
  const viewCount = fullRecord ? fullRecord.view_count : undefined;
  const likeCount = fullRecord ? fullRecord.like_count : undefined;
  const commentCount = fullRecord ? fullRecord.comment_count : undefined;

  const hasView = typeof viewCount === 'number' && Number.isFinite(viewCount);
  const hasComment = typeof commentCount === 'number' && Number.isFinite(commentCount);
  const hasLike = typeof likeCount === 'number' && Number.isFinite(likeCount);

  if (!hasView) {
    return {
      attention_potential: 'NOT_DETERMINED',
      attention_potential_score: null,
      attention_potential_inputs_used: [],
      like_signal_excluded_reason: null,
      attention_potential_formula_version: ATTENTION_POTENTIAL_FORMULA_VERSION,
    };
  }

  // A like_count of exactly 0 is genuinely ambiguous: YouTube's API returns the
  // same literal 0 both when a creator has hidden public like counts and when a
  // video truly has zero likes (confirmed on a real record during the adapter
  // build). Per Section 24 (insufficient information over guessing), a
  // like_count of 0 is excluded from the formula entirely rather than scored
  // as real negative evidence -- treated as unknown, not as a real zero.
  const likeUsable = hasLike && likeCount > 0;

  const components = [];
  components.push({ name: 'view', weight: WEIGHT_VIEW, score: bucketScore(viewCount, VIEW_COUNT_THRESHOLDS) });
  if (hasComment) {
    components.push({ name: 'comment', weight: WEIGHT_COMMENT, score: bucketScore(commentCount, COMMENT_COUNT_THRESHOLDS) });
  }
  if (likeUsable) {
    components.push({ name: 'like', weight: WEIGHT_LIKE, score: bucketScore(likeCount, LIKE_COUNT_THRESHOLDS) });
  }

  const totalWeight = components.reduce((sum, c) => sum + c.weight, 0);
  const weightedSum = components.reduce((sum, c) => sum + c.weight * c.score * 10, 0);
  const compositeScore = totalWeight > 0 ? Math.round(weightedSum / totalWeight) : 0;

  const status = ATTENTION_STATUS_THRESHOLDS.find((t) => compositeScore >= t.min).status;

  return {
    attention_potential: status,
    attention_potential_score: compositeScore,
    attention_potential_inputs_used: components.map((c) => c.name),
    like_signal_excluded_reason: hasLike && !likeUsable ? 'zero_or_hidden_ambiguous' : null,
    attention_potential_formula_version: ATTENTION_POTENTIAL_FORMULA_VERSION,
  };
}
// --- end FIX 1 ---

const results = uor01.records.map((rec) => {
  const rs = rec.raw_signal || {};
  const text = `${rs.opportunity_title || ''} ${rs.problem || ''} ${rs.demand_signal || ''}`;
  const platforms = PLATFORMS.filter(([t,e]) => keywordRegex(t,e).test(text)).map(([t]) => t.trim());
  const formats = FORMATS.filter(([t,e]) => keywordRegex(t,e).test(text)).map(([t]) => t.trim());
  const inUor06ContentTag = contentTagMembers.has(rec.opportunity_id);

  let content_opportunity_status;
  if (platforms.length > 0 && formats.length > 0) content_opportunity_status = 'GENUINE_CONTENT_SIGNAL';
  else if (platforms.length > 0 || formats.length > 0 || inUor06ContentTag) content_opportunity_status = 'WEAK_TANGENTIAL_MENTION';
  else content_opportunity_status = 'NO_CONTENT_SIGNAL_DETECTED';

  const factors = rec.scoring_factors || {};
  const autoEstimateRaw = factors.automation_potential?.estimate;
  const automation_potential_pct = typeof autoEstimateRaw === 'number' ? autoEstimateRaw * 10 : null;

  const riskTerms = [['scraping',false],['scrape',false],['bot',true],['bots',true],['automat',false]];
  const mentionsRiskTerm = riskTerms.some(([t, exact]) => keywordRegex(t, exact).test(text));
  const copyright_platform_risk_flag = (platforms.length > 0 && mentionsRiskTerm) || rec.compliance_review_required === true;

  const attention = computeAttentionPotential(rec.full_record);

  return {
    opportunity_id: rec.opportunity_id,
    content_platform_mentioned: platforms,
    content_format_mentioned: formats,
    uor06_content_tag_membership: inUor06ContentTag,
    content_opportunity_status,
    attention_potential: attention.attention_potential,
    attention_potential_score: attention.attention_potential_score,
    attention_potential_inputs_used: attention.attention_potential_inputs_used,
    like_signal_excluded_reason: attention.like_signal_excluded_reason,
    attention_potential_formula_version: attention.attention_potential_formula_version,
    monetization_potential: 'NOT_DETERMINED',
    automation_potential_pct,
    copyright_platform_risk_flag,
    formula_version: 'uor07-v1-content-signal-2026-09-06',
    computed_at: new Date().toISOString(),
  };
});

const fileText = results.map((r) => JSON.stringify(r)).join('\n') + '\n';

return [{
  json: {
    uor01_record_count: uor01.records.length,
    uor01_parse_failures: uor01.failures,
    uor06_record_count: uor06.records.length,
    uor06_parse_failures: uor06.failures,
    status_breakdown: results.reduce((acc, r) => { acc[r.content_opportunity_status] = (acc[r.content_opportunity_status]||0)+1; return acc; }, {}),
    attention_breakdown: results.reduce((acc, r) => { acc[r.attention_potential] = (acc[r.attention_potential]||0)+1; return acc; }, {}),
    file_text: fileText,
  },
}];
